mapper.select:
SELECT  FROM document_delivery
WHERE workspace_id = #{workspaceId} AND document_id = #{documentId}
ORDER BY id DESC

SELECT  FROM document_delivery
WHERE workspace_id = #{workspaceId} AND id = #{id}
FOR UPDATE

SELECT  FROM document_delivery
WHERE workspace_id = #{workspaceId}
  AND document_id = #{documentId}
  AND status IN ('sent', 'viewed')
LIMIT 1

SELECT  FROM document_delivery
WHERE workspace_id = #{workspaceId}
  AND provider = #{provider}
  AND provider_envelope_id = #{providerEnvelopeId}

SELECT id FROM document_delivery
WHERE workspace_id = #{workspaceId}
  AND status IN ('sent', 'viewed')
  AND expires_at IS NOT NULL
  AND expires_at <= #{now}
ORDER BY expires_at, id
LIMIT #{limit}

mapper.insert:
INSERT INTO document_delivery (
  workspace_id, deal_id, document_id, provider, provider_envelope_id, status, message,
  expires_at, sent_by
) VALUES (
  #{workspaceId}, #{dealId}, #{documentId}, #{provider}, #{providerEnvelopeId}, #{status},
  #{message}, #{expiresAt}, #{sentBy}
)

mapper.update:
UPDATE document_delivery
SET status = 'completed', completed_at = #{completedAt}
WHERE workspace_id = #{workspaceId} AND id = #{id} AND status IN ('sent', 'viewed')

UPDATE document_delivery
SET status = #{status}, terminated_at = #{terminatedAt}, termination_reason = #{reason}
WHERE workspace_id = #{workspaceId} AND id = #{id} AND status IN ('sent', 'viewed')

mapper.insert:
INSERT INTO document_delivery_recipient (
  workspace_id, delivery_id, person_id, name, email, role, recipient_order, status,
  token_hash, token_expires_at, provider_recipient_id
) VALUES (
  #{workspaceId}, #{deliveryId}, #{personId}, #{name}, #{email}, #{role}, #{recipientOrder},
  #{status}, #{tokenHash}, #{tokenExpiresAt}, #{providerRecipientId}
)

mapper.select:
SELECT  FROM document_delivery_recipient
WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId}
ORDER BY recipient_order, id

SELECT FROM document_delivery_recipient WHERE workspace_id = #{workspaceId} AND delivery_id IN
#{deliveryId}
ORDER BY delivery_id, recipient_order, id

SELECT  FROM document_delivery_recipient
WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId} AND id = #{id}
FOR UPDATE

SELECT  FROM document_delivery_recipient
WHERE workspace_id = #{workspaceId} AND token_hash = #{tokenHash}
LIMIT 1

SELECT  FROM document_delivery_recipient
WHERE workspace_id = #{workspaceId}
  AND delivery_id = #{deliveryId}
  AND provider_recipient_id = #{providerRecipientId}
LIMIT 1

SELECT id FROM document_delivery_recipient
WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId}
ORDER BY id

mapper.update:
UPDATE document_delivery_recipient
SET token_hash = #{tokenHash}, token_expires_at = #{tokenExpiresAt},
    provider_recipient_id = #{providerRecipientId}
WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId} AND id = #{id}
  AND status IN ('pending', 'viewed')

UPDATE document_delivery_recipient
SET status = 'completed', typed_name = #{typedName}, decided_at = #{decidedAt},
    evidence_ip_hash = #{evidenceIpHash}, evidence_agent_hash = #{evidenceAgentHash}
WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId} AND id = #{id}
  AND role = 'signer' AND status IN ('pending', 'viewed')

UPDATE document_delivery_recipient
SET status = 'declined', decline_reason = #{reason}, decided_at = #{decidedAt},
    evidence_ip_hash = #{evidenceIpHash}, evidence_agent_hash = #{evidenceAgentHash}
WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId} AND id = #{id}
  AND role = 'signer' AND status IN ('pending', 'viewed')

UPDATE document_delivery_recipient
SET status = #{status}, token_hash = NULL, token_expires_at = NULL
WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId}
  AND status IN ('pending', 'viewed')

    AND id <> #{exceptRecipientId}

UPDATE document_delivery_recipient
SET token_hash = NULL, token_expires_at = NULL
WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId}
  AND token_hash IS NOT NULL

    AND id <> #{exceptRecipientId}

mapper.select:
SELECT COUNT(*) FROM document_delivery_recipient
WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId}
  AND role = 'signer' AND status <> 'completed'

mapper.insert:
INSERT INTO document_delivery_event (
  workspace_id, delivery_id, recipient_id, event_type, source, external_event_id, detail, occurred_at
) VALUES (
  #{workspaceId}, #{deliveryId}, #{recipientId}, #{eventType}, #{source},
  #{externalEventId}, #{detail}, #{occurredAt}
)

mapper.select:
SELECT EXISTS(
  SELECT 1 FROM document_delivery_event
  WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId}
    AND event_type = #{eventType}

      AND recipient_id IS NULL
      AND recipient_id = #{recipientId}

)

SELECT EXISTS(
  SELECT 1 FROM document_delivery_event
  WHERE workspace_id = #{workspaceId} AND delivery_id = #{deliveryId}
    AND external_event_id = #{externalEventId}
)

SELECT FROM document_delivery_event WHERE workspace_id = #{workspaceId} AND delivery_id IN
#{deliveryId}
ORDER BY delivery_id, id

